code.cpp:
class Solution {
public:
    int shortestPathLength(vector<vector<int>>& graph) {
        int n = graph.size();
        int full = (1 << n) - 1;
        vector<vector<bool>> visited(n, vector<bool>(1 << n, false));
        queue<pair<int,int>> q;
        for (int i = 0; i < n; i++) {
            q.push({i, 1 << i});
            visited[i][1 << i] = true;
        }
        int dist = 0;
        while (!q.empty()) {
            int sz = q.size();
            for (int k = 0; k < sz; k++) {
                auto [node, mask] = q.front();
                q.pop();
                if (mask == full) return dist;
                for (int nb : graph[node]) {
                    int nmask = mask | (1 << nb);
                    if (!visited[nb][nmask]) {
                        visited[nb][nmask] = true;
                        q.push({nb, nmask});
                    }
                }
            }
            dist++;
        }
        return -1;
    }
};
